import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String S = br.readLine();
        if (S == null) S = "";
        String P = br.readLine();
        if (P == null) P = "";

        List<Integer> result = rabinKarp(S, P);

        StringBuilder sb = new StringBuilder();
        if (result.isEmpty()) {
            sb.append("-1");
        } else {
            for (int i = 0; i < result.size(); i++) {
                if (i > 0) sb.append(' ');
                sb.append(result.get(i));
            }
        }
        System.out.print(sb.toString());
    }

    private static List<Integer> rabinKarp(String text, String pattern) {
        List<Integer> result = new ArrayList<>();
        int n = text.length();
        int m = pattern.length();

        if (m == 0 || n == 0 || m > n) {
            return result;
        }

        final long mod = 1000000007L;
        final long base = 256L;

        long patternHash = 0;
        long textHash = 0;
        long power = 1;

        for (int i = 0; i < m; i++) {
            patternHash = (patternHash * base + pattern.charAt(i)) % mod;
            textHash = (textHash * base + text.charAt(i)) % mod;
        }

        for (int i = 1; i < m; i++) {
            power = (power * base) % mod;
        }

        for (int i = 0; i <= n - m; i++) {
            if (patternHash == textHash) {
                if (text.substring(i, i + m).equals(pattern)) {
                    result.add(i);
                }
            }

            if (i < n - m) {
                textHash = (textHash * base - text.charAt(i) * power + text.charAt(i + m)) % mod;
                if (textHash < 0) {
                    textHash += mod;
                }
                textHash = textHash % mod;
            }
        }

        return result;
    }
}
